import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const files = {
  market: "data/market-snapshot.json",
  history: "data/market-history.json",
  news: "data/news.json"
};

const payload = {};
for (const [key, relativePath] of Object.entries(files)) {
  try {
    payload[key] = JSON.parse(await readFile(path.resolve(root, relativePath), "utf8"));
  } catch {
    payload[key] = null;
  }
}

const output = [
  "/* Generated by scripts/build-embedded-data.mjs. */",
  `window.__AURUM_DATA__ = ${JSON.stringify(payload)};`,
  ""
].join("\n");

await writeFile(path.resolve(root, "data/embedded-data.js"), output);
console.log("Updated data/embedded-data.js.");
